if (rbAllY.Checked)
            {
                //Find z...
                //myPlot.lMatrix[nMatrix].lz[0][nZ]=[ztop1, ztop2, zbot1, zbot2]

                double zLoc = ((double)nudZ.Value + 1.0) * (zTop - zBot) / 2.0 + zBot;

                //Find Titles
                sLocation = "x = " + xLoc + ", z = " + zLoc;
                sTitle = "Results between fibers " + cbFiberQueryPair.Text + " at " + sLocation;
                xAxis = "y";


                for (int i = 0; i < nPoints; i++)
                {
                    //This is y... (0 to d)
                    xValue[i] = myPlot.lMatrix[nMatrix].ld12[nLStep - 1] * i / (nPoints - 1.0);
                    Result[i] = myPlot.lMatrix[nMatrix].DecideOnOutput(cbPlotType.SelectedIndex, cbPlotComponent.SelectedIndex,
                        xLoc, xValue[i], zLoc, myPlot.lMatrix[nMatrix].lq[nLStep - 1], nLStep - 1);
                }
            }
            else
            {
                sLocation = "x = " + xLoc + ", y = " + cbYPointQuery.Text[nY];
                sTitle = "Results between fibers " + cbFiberQueryPair.Text + " at " + sLocation;
                xAxis = "z";

                for (int i = 0; i < nPoints; i++)
                {
                    xValue[i] = (i / (nPoints - 1.0)) * (zTop - zBot) + zBot;
                    //Decide on y
                    double yLoc = 0;
                    switch (nY)
                    {
                        case 0:
                            yLoc = myPlot.lMatrix[nMatrix].CalculateYAtLeftFiber(xValue[i]);
                            break;
                        case 1:
                            yLoc = myPlot.lMatrix[nMatrix].ld12[0] / 2.0;
                            break;
                        case 2:
                            yLoc = myPlot.lMatrix[nMatrix].CalculateYAtRightFiber(xValue[i]);
                            break;
                    }
                    Result[i] = myPlot.lMatrix[nMatrix].DecideOnOutput(cbPlotType.SelectedIndex, cbPlotComponent.SelectedIndex,
                        xLoc, yLoc, xValue[i], myPlot.lMatrix[nMatrix].lq[nLStep - 1], nLStep - 1);

                }
            }

